export const envelope = [32, 22, 32];

export default function build(api) {
  const [sizeX, sizeY, sizeZ] = api.size;

  // Resolve world theme palettes with modern industrial fallbacks
  const concrete = api.theme.stone?.primary || "minecraft:stone";
  const concreteAccent = api.theme.stone?.accent || "minecraft:polished_andesite";
  const concreteWall = api.theme.stone?.wall || "minecraft:stone_brick_wall";
  const concreteSlab = api.theme.stone?.slab || "minecraft:smooth_stone_slab[type=bottom]";
  const plinth = api.theme.ground?.plinth || "minecraft:deepslate";
  const pavement = api.theme.ground?.pavement || "minecraft:smooth_stone";

  // Specialized high-tech and apocalyptic ruin materials
  const metalCore = "minecraft:iron_block";
  const blastArmor = "minecraft:polished_deepslate";
  const blastBricks = "minecraft:deepslate_bricks";
  const blastTile = "minecraft:deepslate_tiles";
  const conduitGlow = "minecraft:sea_lantern";
  const conduitPipe = "minecraft:cyan_terracotta";
  const yellowHaz = "minecraft:yellow_concrete";
  const blackHaz = "minecraft:black_concrete";
  const ironBars = "minecraft:iron_bars";
  const chainY = "minecraft:chain[axis=y]";
  const chainX = "minecraft:chain[axis=x]";
  const chainZ = "minecraft:chain[axis=z]";
  const moss = "minecraft:moss_block";
  const leaves1 = "minecraft:flowering_azalea_leaves[persistent=true]";
  const leaves2 = "minecraft:oak_leaves[persistent=true]";
  const solarPanel = "minecraft:daylight_detector";
  const lightningRod = "minecraft:lightning_rod[facing=up]";
  const lodestone = "minecraft:lodestone";
  const ironTrapdoor = "minecraft:iron_trapdoor[half=top]";

  // 3D voxel working grid
  const grid = Array.from({ length: sizeX }, () =>
    Array.from({ length: sizeY }, () => new Array(sizeZ).fill(null))
  );

  function set(x, y, z, block) {
    if (x >= 0 && x < sizeX && y >= 0 && y < sizeY && z >= 0 && z < sizeZ) {
      grid[x][y][z] = block;
    }
  }

  function get(x, y, z) {
    if (x >= 0 && x < sizeX && y >= 0 && y < sizeY && z >= 0 && z < sizeZ) {
      return grid[x][y][z];
    }
    return null;
  }

  function isSolid(x, y, z) {
    const b = get(x, y, z);
    return b !== null && !b.includes("vine") && !b.includes("carpet");
  }

  // Seeded PRNG helpers
  function rand() {
    return api.random();
  }

  // --- 1. BASE LEVEL (Y = 0) FOUNDATION & APPROACH TRENCH ---
  for (let x = 0; x < sizeX; x++) {
    for (let z = 0; z < sizeZ; z++) {
      // Approach trench floor (Z: 0..13, X: 13..18)
      if (z <= 13 && x >= 13 && x <= 18) {
        if (x === 15 || x === 16) {
          set(x, 0, z, conduitGlow); // Glowing center conduit strip
        } else if ((x + z) % 3 === 0) {
          set(x, 0, z, blastArmor);
        } else {
          set(x, 0, z, pavement);
        }
      }
      // Bunker interior floor (X: 10..21, Z: 14..26)
      else if (x >= 10 && x <= 21 && z >= 14 && z <= 26) {
        if (x === 15 || x === 16) {
          set(x, 0, z, conduitGlow);
        } else if (z === 20 || z === 21) {
          set(x, 0, z, conduitPipe);
        } else {
          set(x, 0, z, (x + z) % 2 === 0 ? blastTile : blastArmor);
        }
      }
      // Massive foundation base
      else {
        set(x, 0, z, (x * z) % 5 === 0 ? plinth : concrete);
      }
    }
  }

  // --- 2. RUINED SKYSCRAPER CORNER PILLARS ---
  // Pillar 1: North-West Pillar (X: 2..6, Z: 2..6)
  for (let x = 2; x <= 6; x++) {
    for (let z = 2; z <= 6; z++) {
      const topH = 13 + Math.floor(rand() * 4);
      for (let y = 1; y <= topH; y++) {
        set(x, y, z, rand() < 0.7 ? concrete : concreteAccent);
      }
      // Rebar steel exposed
      if (rand() < 0.4) {
        set(x, topH + 1, z, ironBars);
        if (rand() < 0.5) set(x, topH + 2, z, lightningRod);
      }
    }
  }

  // Pillar 2: North-East Pillar (X: 25..29, Z: 2..6)
  for (let x = 25; x <= 29; x++) {
    for (let z = 2; z <= 6; z++) {
      const topH = 11 + Math.floor(rand() * 4);
      for (let y = 1; y <= topH; y++) {
        set(x, y, z, rand() < 0.75 ? concrete : blastArmor);
      }
      if (rand() < 0.45) {
        set(x, topH + 1, z, ironBars);
      }
    }
  }

  // Pillar 3: South-West Pillar (Main Tower Column & Comm Mast, X: 2..7, Z: 24..29)
  for (let x = 2; x <= 7; x++) {
    for (let z = 24; z <= 29; z++) {
      for (let y = 1; y <= 18; y++) {
        set(x, y, z, (x === 2 || z === 29) ? blastArmor : concrete);
      }
    }
  }
  // Vertical high-tech power trunk on SW pillar
  for (let y = 1; y <= 18; y++) {
    if (y % 4 === 0) {
      set(6, y, 24, conduitGlow);
    } else {
      set(6, y, 24, conduitPipe);
    }
  }

  // Solar & Comm Array Platform on top of SW Pillar (Y = 19..21)
  for (let x = 2; x <= 7; x++) {
    for (let z = 24; z <= 29; z++) {
      set(x, 19, z, metalCore);
    }
  }
  // Perimeter guard railing
  for (let x = 2; x <= 7; x++) {
    set(x, 20, 24, ironBars);
    set(x, 20, 29, ironBars);
  }
  for (let z = 24; z <= 29; z++) {
    set(2, 20, z, ironBars);
    set(7, 20, z, ironBars);
  }
  // Solar panels and sensor dish
  set(4, 20, 26, solarPanel);
  set(5, 20, 26, solarPanel);
  set(4, 20, 27, solarPanel);
  set(5, 20, 27, solarPanel);
  set(3, 20, 25, lodestone);
  set(3, 21, 25, ironBars);
  set(3, 21, 25, lightningRod);
  set(6, 20, 28, conduitGlow);
  set(6, 21, 28, lightningRod);

  // Pillar 4: South-East Pillar (X: 25..29, Z: 24..29)
  for (let x = 25; x <= 29; x++) {
    for (let z = 24; z <= 29; z++) {
      const topH = 14 + Math.floor(rand() * 3);
      for (let y = 1; y <= topH; y++) {
        set(x, y, z, rand() < 0.7 ? concrete : concreteAccent);
      }
      if (rand() < 0.4) {
        set(x, topH + 1, z, ironBars);
      }
    }
  }

  // --- 3. REINFORCED BUNKER CASING & BLAST WALLS ---
  // Outer bunker shell bounding box: X: 8..23, Z: 7..28, Y: 1..8
  for (let x = 8; x <= 23; x++) {
    for (let z = 7; z <= 28; z++) {
      for (let y = 1; y <= 8; y++) {
        const isWallX = (x <= 9 || x >= 22);
        const isWallZ = (z === 7 || z === 8 || z >= 27);
        const isRoof = (y >= 7);
        const isDivider = (z === 13);

        if (isWallX || isWallZ || isRoof || isDivider) {
          if (y === 7 && (x === 15 || x === 16) && z >= 8 && z <= 26) {
            set(x, y, z, conduitGlow); // Ceiling conduit run
          } else if (isRoof) {
            set(x, y, z, (x + z) % 3 === 0 ? blastArmor : blastTile);
          } else {
            set(x, y, z, (y === 1 || y === 6) ? blastArmor : blastBricks);
          }
        }
      }
    }
  }

  // Generator & ventilation module on bunker roof (X: 9..12, Z: 9..12, Y: 8..9)
  for (let x = 9; x <= 12; x++) {
    for (let z = 9; z <= 12; z++) {
      set(x, 8, z, metalCore);
      if (x === 10 && z === 10) {
        set(x, 9, z, "minecraft:blast_furnace[facing=north]");
      } else if (x === 11 && z === 10) {
        set(x, 9, z, conduitGlow);
      } else {
        set(x, 9, z, ironTrapdoor);
      }
    }
  }

  // --- 4. THE BLAST DOOR & AIRLOCK PORTAL (Z: 6..8, X: 11..20) ---
  // Heavy portal framing
  for (let x = 11; x <= 20; x++) {
    for (let y = 1; y <= 6; y++) {
      // Outer jambs and lintel at Z=7
      if (x <= 13 || x >= 18 || y >= 5) {
        set(x, y, 7, metalCore);
        set(x, y, 6, blastArmor);
      }
    }
  }

  // Warning hazard striping along the entrance base
  set(12, 1, 6, yellowHaz);
  set(13, 1, 6, blackHaz);
  set(18, 1, 6, blackHaz);
  set(19, 1, 6, yellowHaz);
  set(12, 2, 6, blackHaz);
  set(13, 2, 6, yellowHaz);
  set(18, 2, 6, yellowHaz);
  set(19, 2, 6, blackHaz);

  // Status lamps above blast door
  set(15, 5, 6, conduitGlow);
  set(16, 5, 6, conduitGlow);

  // Blast Door leaves at Z = 8 (Heavy hydraulic mechanism, partially opened)
  for (let y = 1; y <= 4; y++) {
    set(13, y, 8, metalCore);
    set(14, y, 8, blastArmor);
    set(17, y, 8, blastArmor);
    set(18, y, 8, metalCore);
  }
  // Overhead hydraulic gate track
  for (let x = 14; x <= 17; x++) {
    set(x, 4, 7, ironBars);
  }

  // Security scanner / biometric terminal
  set(12, 2, 5, lodestone);
  set(12, 3, 5, lightningRod);

  // Trench side retaining walls (Z: 1..6)
  for (let z = 1; z <= 6; z++) {
    for (let y = 1; y <= 5; y++) {
      set(12, y, z, blastArmor);
      set(19, y, z, blastArmor);
    }
  }

  // Trench perimeter sensor pylons at Z = 1
  set(12, 1, 1, metalCore);
  set(12, 2, 1, ironBars);
  set(12, 3, 1, lightningRod);
  set(19, 1, 1, metalCore);
  set(19, 2, 1, ironBars);
  set(19, 3, 1, lightningRod);

  // --- 5. COLLAPSED SKYSCRAPER PANCAKED SLABS & RUBBLE ---
  // Massive sloping floor slab leaning from Pillar 3 over the bunker
  for (let x = 4; x <= 26; x++) {
    for (let z = 12; z <= 26; z++) {
      const ySlope = Math.round(16 - (x - 4) * 0.35 - (26 - z) * 0.28);
      if (ySlope >= 8 && ySlope <= 17) {
        set(x, ySlope, z, rand() < 0.7 ? concrete : concreteAccent);
        set(x, ySlope - 1, z, concrete);
        // Vegetation growing in cracks
        if (rand() < 0.25) {
          set(x, ySlope + 1, z, rand() < 0.5 ? moss : leaves2);
        }
      }
    }
  }

  // Broken overhang slab above the blast entrance (X: 8..23, Z: 3..8, Y: 8..9)
  for (let x = 8; x <= 23; x++) {
    for (let z = 3; z <= 8; z++) {
      if (z >= 6 || (x >= 10 && x <= 21 && rand() < 0.8)) {
        set(x, 8, z, concrete);
        set(x, 9, z, rand() < 0.5 ? concreteAccent : moss);
      }
    }
  }
  // Rebar hanging from the shattered front edge
  for (let x = 9; x <= 22; x += 2) {
    if (get(x, 8, 4) !== null) {
      set(x, 8, 3, ironBars);
    }
  }

  // Retaining rubble banks on the West and East flanks
  for (let z = 6; z <= 26; z++) {
    // West rubble mound
    for (let x = 0; x <= 7; x++) {
      const maxH = Math.min(7, Math.floor(x * 0.9 + (z > 16 ? 2 : 1)));
      for (let y = 1; y <= maxH; y++) {
        set(x, y, z, rand() < 0.6 ? concrete : plinth);
      }
      if (maxH >= 1 && rand() < 0.3) {
        set(x, maxH + 1, z, moss);
      }
    }
    // East rubble mound
    for (let x = 24; x <= 31; x++) {
      const maxH = Math.min(7, Math.floor((31 - x) * 0.9 + (z > 16 ? 2 : 1)));
      for (let y = 1; y <= maxH; y++) {
        set(x, y, z, rand() < 0.6 ? concrete : plinth);
      }
      if (maxH >= 1 && rand() < 0.3) {
        set(x, maxH + 1, z, moss);
      }
    }
  }

  // --- 6. MAKESHIFT CAMOUFLAGE NETTING OVER ENTRANCE TRENCH ---
  // Overhead cable suspension grid at Y = 6..7 spanning X: 11..20, Z: 1..7
  for (let x = 12; x <= 19; x++) {
    for (let z = 1; z <= 6; z++) {
      const isCable = (x === 13 || x === 15 || x === 17 || x === 19 || z === 2 || z === 4 || z === 6);
      if (isCable) {
        set(x, 6, z, chainZ);
      }
      // Draped camouflage canopy
      if (rand() < 0.68) {
        const leafType = rand() < 0.4 ? leaves1 : (rand() < 0.7 ? leaves2 : moss);
        set(x, 7, z, leafType);
      }
      // Hanging foliage strands
      if (rand() < 0.2) {
        set(x, 5, z, leaves2);
        if (rand() < 0.3) set(x, 4, z, leaves2);
      }
    }
  }

  // --- 7. SANCTUARY INTERIOR AIR CLEARANCE ---
  // Ensure the airlock tunnel is completely walk-through
  for (let x = 14; x <= 17; x++) {
    for (let z = 0; z <= 13; z++) {
      for (let y = 1; y <= 4; y++) {
        // Keep clear walk path (blast door panels are on x=13..14, 17..18 at z=8)
        if (z !== 8 || (x === 15 || x === 16)) {
          set(x, y, z, null);
        }
      }
    }
  }

  // Internal blast door dividing vestibule from main hall (Z = 13)
  for (let x = 14; x <= 17; x++) {
    for (let y = 1; y <= 4; y++) {
      set(x, y, 13, null); // Open archway into the main hall
    }
  }

  // Completely carve out the high-tech bunker interior hall
  for (let x = 10; x <= 21; x++) {
    for (let z = 14; z <= 26; z++) {
      for (let y = 1; y <= 6; y++) {
        set(x, y, z, null);
      }
    }
  }

  // Interior corner conduit columns
  const corners = [
    [10, 14], [21, 14], [10, 26], [21, 26]
  ];
  for (const [cx, cz] of corners) {
    for (let y = 1; y <= 6; y++) {
      set(cx, y, cz, (y === 2 || y === 5) ? conduitGlow : conduitPipe);
    }
  }

  // --- 8. VINES & HANGING VEGETATION ON EXTERIOR WALLS ---
  function tryAddVine(x, y, z) {
    if (get(x, y, z) !== null) return;
    if (z > 0 && isSolid(x, y, z - 1)) {
      set(x, y, z, "minecraft:vine[north=true]");
    } else if (z < sizeZ - 1 && isSolid(x, y, z + 1)) {
      set(x, y, z, "minecraft:vine[south=true]");
    } else if (x > 0 && isSolid(x - 1, y, z)) {
      set(x, y, z, "minecraft:vine[west=true]");
    } else if (x < sizeX - 1 && isSolid(x + 1, y, z)) {
      set(x, y, z, "minecraft:vine[east=true]");
    }
  }

  for (let x = 0; x < sizeX; x++) {
    for (let z = 0; z < sizeZ; z++) {
      // Hang vines down exterior faces
      for (let y = 2; y <= 12; y++) {
        if (rand() < 0.12) {
          tryAddVine(x, y, z);
        }
      }
    }
  }

  // --- 9. EMIT TO WORLD API ---
  for (let x = 0; x < sizeX; x++) {
    for (let y = 0; y < sizeY; y++) {
      for (let z = 0; z < sizeZ; z++) {
        const block = grid[x][y][z];
        if (block !== null) {
          api.set(x, y, z, block);
        }
      }
    }
  }

  return {
    name: "high_tech_sanctuary_bunker",
    seatY: 0,
    anchors: {
      front: [15, 1, 0],
      door: [15, 1, 7],
      comm_array: [3, 21, 25]
    },
    interiors: [
      {
        min: [10, 1, 14],
        max: [21, 6, 26],
        kind: "bunker"
      }
    ]
  };
}

